    execution = runner.start_execution(VOLUME_TO_SURFACE_MAPPING_METADATA)
    execution.params(params)
    args = volume_to_surface_mapping_cargs(params, execution)
    out = volume_to_surface_mapping_outputs(params, execution)
    execution.run(args)
    return out

